EventTags UserInterests::getEventTags(const DbClientPtr &clientPtr) const {
    static const std::string sql = "select * from event_tags where id = $1";
    Result r(nullptr);
    {
        auto binder = *clientPtr << sql;
        binder << *eventTagId_ << Mode::Blocking >>
            [&r](const Result &result) { r = result; };
        binder.exec();
    }
    if (r.size() == 0)
    {
        throw UnexpectedRows("0 rows found");
    }
    else if (r.size() > 1)
    {
        throw UnexpectedRows("Found more than one row");
    }
    return EventTags(r[0]);
}

void UserInterests::getEventTags(const DbClientPtr &clientPtr,
                                 const std::function<void(EventTags)> &rcb,
                                 const ExceptionCallback &ecb) const
{
    static const std::string sql = "select * from event_tags where id = $1";
    *clientPtr << sql
               << *eventTagId_
               >> [rcb = std::move(rcb), ecb](const Result &r){
                    if (r.size() == 0)
                    {
                        ecb(UnexpectedRows("0 rows found"));
                    }
                    else if (r.size() > 1)
                    {
                        ecb(UnexpectedRows("Found more than one row"));
                    }
                    else
                    {
                        rcb(EventTags(r[0]));
                    }
               }
               >> ecb;
}

